INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(5164, 'zhTW', '牠在銀月城翻找魔法垃圾時碰上了點麻煩。幸好，當時有你在旁邊幫忙！', '|cFFFFD200發現：|r銀月城|n', 69497),
(5077, 'zhTW', '', '', 69497);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(318840, 'zhTW', '', '靈魂是會互惠互利的，對吧？明天再來試試你的運氣吧。', 69497),
(317406, 'zhTW', '（痛苦哀號）', '', 69497),
(317402, 'zhTW', '（窒息）', '', 69497),
(317398, 'zhTW', '（沉重喘氣）', '', 69497),
(318450, 'zhTW', '', '那就是我們的目標。', 69497),
(318448, 'zhTW', '', '快，躲進暗影裡！', 69497),
(314045, 'zhTW', '', '別再嚇我了。', 69497),
(314044, 'zhTW', '', '重返戰場。', 69497),
(314043, 'zhTW', '', '你要當我的戰友，就得持續戰下去。', 69497),
(314042, 'zhTW', '', '別死在我眼前！', 69497),
(314010, 'zhTW', '', '撤退！我們必須重整旗鼓。', 69497),
(313727, 'zhTW', '', '我會掩護你。', 69497),
(313723, 'zhTW', '', '殺了它。強化我！', 69497),
(313717, 'zhTW', '', '瓦麗拉只能有一個。解決它！', 69497),
(321873, 'zhTW', '', '握住她的手。', 69497),
(320494, 'zhTW', '', '謝謝你，$n。就算你救不了他們，這個情報能救很多人的命。', 69497),
(319326, 'zhTW', '1…2…3…\n\n喔！呃…嗨！\n\n我們只是在玩躲貓貓。其他人正在躲起來。他們總是叫我當鬼，因為他們說我太容易找到了…\n\n不過，你好像是很厲害的追尋者！比我更厲害…\n\n你要試著去找他們嗎？\n\n不過我得先提醒你…他們都很會躲。\n\n5…6…7…', '1…2…3…\n\n喔！呃…嗨！\n\n我們只是在玩躲貓貓。其他人正在躲起來。他們總是叫我當鬼，因為他們說我太容易找到了…\n\n不過，你好像是很厲害的追尋者！比我更厲害…\n\n你要試著去找他們嗎？\n\n不過我得先提醒你…他們都很會躲。\n\n5…6…7…', 69497),
(318831, 'zhTW', '小偷…', '', 69497),
(318533, 'zhTW', '', '我們所經歷的一切…\n\n不可能毫無意義。', 69497),
(318238, 'zhTW', '什麼！祂屠殺了一整個村子？什麼樣的羅亞…', '', 69497),
(317991, 'zhTW', '拜託！如果你不使用恩惠，我就會永遠困在這裡！我會給你想要的一切！只要使用那個恩惠就好！', '', 69497),
(317886, 'zhTW', '你真好心，救了這隻可憐的老狐狸！你對我有恩，我願意三倍奉還！給你三個恩惠。\n\n第一個恩惠你想要什麼？', '', 69497),
(317371, 'zhTW', '我…我父母…', '', 69497),
(317362, 'zhTW', '保持專注。', '', 69497),
(316476, 'zhTW', '祂們辜負了祖父，還有叔叔，祂們也會辜負你。', '', 69497),
(316469, 'zhTW', '', '你為什麼要這麼做？', 69497),
(316440, 'zhTW', '我望向虛無時，你知道我看到了什麼嗎？', '', 69497),
(315773, 'zhTW', '射門！對頭骨足球來說是個精彩的一天！這天值得名留青史，我也永遠不會忘記。', '', 69497),
(315751, 'zhTW', '腳步快速俐落！頭槌強力凶狠！', '', 69497),
(315736, 'zhTW', '先生小姐們，是時候再次見證賽事王者中的王者，頭骨足球！', '', 69497),
(315715, 'zhTW', '據說要使用兩塊靈魂碎片才能召喚這個參賽者！他很巨大，身體是藍色的，還超級討厭這個地方！他就是古斯卡！', '', 69497),
(315706, 'zhTW', '即使是一群無名小…等等，那是$pr和沒穿褲子的精靈嗎？他們還真大膽！', '', 69497),
(314378, 'zhTW', '讓實驗…開始吧！', '', 69497),
(313757, 'zhTW', '很高興能在這裡看到一些新面孔。我和我的船員已經擱淺在這裡超過七年了，逐漸開始認為我們可能得在這裡落地生根了！', '', 69497),
(313655, 'zhTW', '毒液深入體內。直取骨肉！', '', 69497),
(313623, 'zhTW', '', '歐薇娜？現在你眼前的是尼札利。立刻跪下，我就饒你一命。', 69497),
(313438, 'zhTW', '', '現在又變得無聊了。', 69497),
(313337, 'zhTW', '給我滾開！', '', 69497),
(313292, 'zhTW', '托爾托人…都是魚腥味和海水味。噁心至極！', '', 69497),
(313265, 'zhTW', '得救了？而且竟然是靠外來者的幫助。我欠你一份，$n。', '', 69497),
(313191, 'zhTW', '哈囉！你看起來就是我要找的那種優秀且正直的年輕$c。\n\n我們有許多德高望重的長者在納爾丁劫掠者突襲營地時，根本就來不及逃走。\n\n幾百年下來，他們有著很厚的殼，以及畢生習得的知識，但只要是跟速度有關的事情，他們就完全沒轍。\n\n你可以幫一些長者重獲自由嗎？\n\n如果你剛好有看到被丟棄的神器或卷軸，也順便拿回來，幫助我們重建新營地。', '哈囉！你看起來就是我要找的那種優秀且正直的年輕$c。\n\n我們有許多德高望重的長者在納爾丁劫掠者突襲營地時，根本就來不及逃走。\n\n幾百年下來，他們有著很厚的殼，以及畢生習得的知識，但只要是跟速度有關的事情，他們就完全沒轍。\n\n你可以幫一些長者重獲自由嗎？\n\n如果你剛好有看到被丟棄的神器或卷軸，也順便拿回來，幫助我們重建新營地。', 69497),
(313079, 'zhTW', '不！一切還沒完呢…', '', 69497),
(312978, 'zhTW', '啊！經過了數千年，我終於自由了！是時候找個合適的身體了。', '', 69497),
(312896, 'zhTW', '', '嗯…你看起來很煩惱。是頭痛嗎？還是詛咒？又或者是糟糕的決策？這三種我都治，有時候療法都一樣。', 69497),
(312775, 'zhTW', '', '呵。哈巫拉，小心點。你聽起來越來越像個阿曼尼了。', 69497),
(312568, 'zhTW', '紅通通。又黏稠。<啜吸>真美味。', '', 69497),
(312407, 'zhTW', '', '嘿嘿。看來…你們又來了？', 69497),
(312364, 'zhTW', '', '快看！大門開啟了！我來了，祖爾詹。再撐一會…', 69497),
(312317, 'zhTW', '這塊土地有著比毒蛇更恐怖的存在！', '', 69497),
(312311, 'zhTW', '你手上的東西…散發著力量的光芒…', '', 69497),
(311954, 'zhTW', '', '你有…找到詹嗎？', 69497),
(311951, 'zhTW', '真是迷人…這是真正的苦痛泉源。', '', 69497),
(311938, 'zhTW', '你的臉色有點蒼白。或許是毒液的影響？', '', 69497),
(311936, 'zhTW', '毒蛇之牙已被拔起。獵場依然由你支配。', '', 69497),
(311893, 'zhTW', '', '這才算是值得乾杯的選擇。', 69497),
(311857, 'zhTW', '再來一輪，是吧？我喜歡你這種類型的麻煩精，老熊貓。', '', 69497),
(311849, 'zhTW', '麻煩還是會找上門啊，朋友，但好酒也是…通常兩者會同時上門。', '', 69497),
(311846, 'zhTW', '我只能說，你的確不負名聲。這酒只適合慢慢啜飲啊。', '', 69497),
(311845, 'zhTW', '好啦…你覺得呢？', '', 69497),
(311800, 'zhTW', '', '哈謝歡迎你。', 69497),
(311779, 'zhTW', '', '珍重再見，可敬的梅德嘉。有其他人來接班了。', 69497),
(311769, 'zhTW', '啊，是探險者夥伴！', '', 69497),
(311762, 'zhTW', '', '就在那裡而已。你能拿去還給他嗎？', 69497),
(311691, 'zhTW', '我們敬重死者，但魂能有其用處。從暴力的傢伙身上收集一些回來吧。', '', 69497),
(311317, 'zhTW', '', '我沒事。只是皮肉傷。我們該到村子裡重整旗鼓。', 69497),
(311250, 'zhTW', '不怎麼好吃…但有新鮮水果可吃，士兵們會很高興的。', '', 69497),
(311241, 'zhTW', '眾靈安息了。我絕不會讓他們的武器白白浪費。', '', 69497),
(310320, 'zhTW', '', '我知道你希望我不要太過擔心，$n。但直到近期，我才知道我的話語是有份量的。為了締結分裂同胞之間的橋樑，我太過急躁了。而如今，阿曼尼蒙受其害。\n\n我想彌補這一切。而且是同心協力。', 69497),
(309826, 'zhTW', '', '不，它消失了。到船附近看看。也許有些靈魂還在甲板上徘徊。', 69497),
(309825, 'zhTW', '', '傑維克？嗯，沒錯。他是很樂天的傢伙。總是願意伸出援手。有一個朋友…好像是…', 69497),
(309540, 'zhTW', '我們必須去幫$n！特肯！別站在那發呆！', '', 69497),
(309165, 'zhTW', '呵。你還信任那些羅亞？祖爾詹現在已經有更強大的力量了。', '', 69497),
(309043, 'zhTW', '', '我們的敵人太難纏了…解決這個威脅，動作快！', 69497),
(308482, 'zhTW', '如果祖爾詹以為我們會讓他代替祖爾賈拉統治，那真的想太美了。', '', 69497),
(308324, 'zhTW', '', '偉大的勝利羅亞啊！阿曼尼族的哈謝，再次呼喚你的力量！', 69497),
(308186, 'zhTW', '瑪拉克雷斯肯定就在神廟裡，和祖爾詹在一起。現在他們兩個都是阿曼尼族的敵人。', '', 69497),
(308043, 'zhTW', '暮光之刃曾是薩拉塔斯的追隨者。他們一定知道她現在在哪裡。\n\n只要從他們身上挖出情報，我們就能找到薩拉塔斯，讓她付出代價。', '', 69497),
(307747, 'zhTW', '', '你看起來不怎麼強。你真的想打一場嗎？你算是值得一戰的對手嗎？', 69497),
(307386, 'zhTW', '我不知道薩拉塔斯去了哪裡。但我知道一旦烏拉特克死去，克希斯就能再次甦醒！', '', 69497),
(307346, 'zhTW', '難道那是…安諾里恩？這怎麼可能！', '', 69497),
(307324, 'zhTW', '對阿拉特而言，我們在晨曦之井的勝利只是一時的。他一心一意只想找到父母…還有薩拉塔斯。', '', 69497),
(304905, 'zhTW', '尼札利！快過來！我們需要你治療！', '尼札利！快過來！我們需要你治療！', 69497),
(304870, 'zhTW', '', '比羅亞更為古老、強大的力量啊！有了這力量，阿曼尼將獲得勝利！', 69497),
(304688, 'zhTW', '哈！這身體任憑我擺布！', '', 69497),
(304072, 'zhTW', '你別想通過。別想偷看。', '', 69497),
(303912, 'zhTW', '', '祂帶我們到這裡，其中肯定有原因。', 69497),
(324314, 'zhTW', '', '為什麼不呢？我是商人，我和聯盟的各種人物都會做買賣。這麼精緻的物品總是會吸引我的興趣。還有你的興趣也是。\n\n還有，如果你想知道，牽引機是西部荒野地精做的，不是人類。', 69497),
(324310, 'zhTW', '', '歡迎。我這裡賣的是來自西部荒野最優質的商品。', 69497),
(317350, 'zhTW', '多謝你的幫忙，也多謝你讓菈烏娜恢復如初。', '', 69497),
(316943, 'zhTW', '', '是你扭曲了他，就像你對我們祖父做的一樣！', 69497),
(316933, 'zhTW', '阿曼尼竟變得如此懦弱…', '', 69497),
(316473, 'zhTW', '讓我們的敵人充滿恐懼的帝國，而不是對騙子魂靈卑躬屈膝。', '', 69497),
(315958, 'zhTW', '太兇狠了！諾克把他狠狠打倒在地！', '', 69497),
(315957, 'zhTW', '怎麼回事？他被諾克擊倒，但又再次爬起來了？他是永遠都不會倒下的！', '', 69497),
(315955, 'zhTW', '他是最厲害的靈長類之王，也是隻力大無窮的猩猩！他就是諾克！', '', 69497),
(315953, 'zhTW', '諾克！', '諾克！', 69497),
(315951, 'zhTW', '我說諾克，你說…', '', 69497),
(315214, 'zhTW', '', '我會加入。\n\n自從你把那個鑰石交給貝拉斯後，我就一直在文庫裡尋找情報。\n\n我們滲入安托洛斯的時候，取得了許多燃燒軍團奪取世界的資訊。\n\n當然，因為也不知道這個鑰石是從哪個世界來的，那些知識可能毫無用處。', 69497),
(315085, 'zhTW', '', '我不知該如何感謝你，$p。\n\n你幫忙找到菈烏娜的解藥，還有尋找斥侯隊的其他成員，這對我們的意義非常重大。', 69497),
(315002, 'zhTW', '我打賭，我能比你先到廣場。我還能讓你先起步。', '', 69497),
(313066, 'zhTW', '毫無意義的掙扎。', '', 69497),
(313039, 'zhTW', '', '屏障開始變弱了！', 69497),
(313036, 'zhTW', '', '祖爾賈拉沒多少時間了。我先去前面偵察，$n，去解除屏障吧！', 69497),
(312774, 'zhTW', '', '詹的行為就像，有背後靈在他身旁看著。好像他一定得讓我們的先祖驕傲。', 69497),
(311940, 'zhTW', '真是冷血又無情。我只能說聲佩服。可惜，只能有一位獵人勝出。', '', 69497),
(311615, 'zhTW', '雖然他並未掌握虛無，我認為他想找到薩拉塔斯的決心使他呼喚聖光的同時，也能承受虛無的存在。', '', 69497),
(311605, 'zhTW', '現在已經有人指控我…和其他虛無精靈…是怪物。我不想讓指控成為事實。', '', 69497),
(310494, 'zhTW', '', '你們都還記得節奏，對吧？', 69497),
(308371, 'zhTW', '', '等等。我聽到…女神的聲音！祂有話想和我們說…', 69497),
(307753, 'zhTW', '現在我們來從這些骨頭汲取出我的靈魂。丟下誘餌！', '', 69497),
(307646, 'zhTW', '', '我只記得那天自己追求著榮耀，但我卻忘了是為何而戰。', 69497),
(307379, 'zhTW', '沒錯。我敢說安諾里恩肯定知道他們打算做什麼。', '', 69497),
(307367, 'zhTW', '呃啊！不！', '', 69497),
(305873, 'zhTW', '', '特弗卡傷得不重，但我得照料他，避免傷口惡化。', 69497),
(304867, 'zhTW', '退後！把傷兵帶回避難所！', '', 69497),
(304624, 'zhTW', '', '閉嘴！這次跟緊一點。', 69497),
(308552, 'zhTW', '絕不能信仰它！它必須被遺忘！', '', 69497);
