INSERT INTO `scenario_step_locale` (`ID`, `locale`, `Description_lang`, `Title_lang`, `VerifiedBuild`) VALUES
(17053, 'zhTW', '進入憤怒之印下方的詛咒廳堂，消滅其中的威脅。', '清理詛咒深淵', 69497),
(17052, 'zhTW', '設法進入詛咒深淵。', '進入詛咒深淵', 69497),
(17048, 'zhTW', '準備進攻墓窖。', '準備進攻', 69497),
(17044, 'zhTW', '進入墓窖並擊敗那裡的敵人。', '清理墓窖', 69497),
(17032, 'zhTW', '做好準備，蛇潮來了。', '自深淵滑出', 69497),
(17030, 'zhTW', '顧焰師正在準備靈魂火堆。', '準備火堆', 69497),
(17028, 'zhTW', '發現了奇怪的儲物箱！', '檢視儲物箱', 69497),
(16919, 'zhTW', '進入多個傳送門並摧毀魯克賈的蛋。', '摧毀窩巢', 69497),
(16918, 'zhTW', '等待傳送門開啟。', '召喚傳送門', 69497),
(16876, 'zhTW', '解鎖儲物箱。', '解鎖儲物箱', 69497),
(16875, 'zhTW', '將三把護杖從每個岩石帶到儲物箱。', '取回護杖', 69497),
(16873, 'zhTW', '收集邪惡靈魂，然後在靈魂火堆燒掉靈魂。攜帶火堆的烈焰，摧毀被褻瀆的石棺。', '淨化不死族', 69497),
(16858, 'zhTW', '利用聖壇收集不潔球體。', '使用大地和天空聖壇', 69497),
(16856, 'zhTW', '殺死毒蛇並打斷儀式，防止神殿淪陷。', '殲滅蛇潮', 69497),
(16853, 'zhTW', '聖壇受到強化，可供使用。', '強化聖壇', 69497),
(17336, 'zhTW', '殺出通往劇毒深淵之心的路，阻止烏拉特克逃離她的牢獄。', '烏拉特克之墓', 69497),
(17329, 'zhTW', '殺出通往劇毒深淵之心的路，正面迎戰烏拉特克。', '烏拉特克之墓', 69497),
(17328, 'zhTW', '埋葬因纏魂者而死去之人的遠古殿堂，現已被毒蛇怪物佔據。', '巨蛇地穴', 69497),
(17327, 'zhTW', '在惡疾之廳中，『惡性之毒』伐許尼克將烏拉特克的毒液蒸餾成更加致命的物質。', '劇毒精華', 69497);
